package com.franco.desco.adapter.in.web.sanitation;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;
public final class SanitationRequests{private SanitationRequests(){}@Schema(name="SanitationCreateRequest")public record Create(@NotNull Long parcelaCultivoId,@NotNull Integer tipoProblemaId,@NotNull Long visitaDeteccionId,@NotNull Instant fechaDeteccion,@PositiveOrZero Integer plantasAfectadas,boolean cantidadEstimada,@NotBlank@Size(max=10)String severidad,@Size(max=500)String observacion){}@Schema(name="SanitationUpdateRequest")public record Update(@NotNull Integer tipoProblemaId,@PositiveOrZero Integer plantasAfectadas,boolean cantidadEstimada,@NotBlank@Size(max=10)String severidad,@Size(max=500)String observacion){}@Schema(name="SanitationChangeStateRequest")public record ChangeState(@NotBlank@Size(max=20)String nuevoEstado,@NotBlank@Size(max=500)String motivo){}@Schema(name="SanitationCloseRequest")public record Close(@NotBlank@Size(max=500)String motivo){}@Schema(name="SanitationTreatmentRequest")public record Treatment(Long visitaTecnicaId,@NotNull Long responsableEmpleadoId,@NotNull Instant fechaHora,@NotBlank@Size(max=300)String tratamiento,@Size(max=160)String producto,@Positive BigDecimal dosis,@Size(max=30)String unidadDosis,@Size(max=400)String observacion){}@Schema(name="SanitationFollowUpRequest")public record FollowUp(Long visitaTecnicaId,@NotNull Instant fechaHora,@PositiveOrZero Integer plantasAfectadas,boolean cantidadEstimada,@NotBlank@Size(max=10)String severidad,@NotBlank@Size(max=20)String resultado,@Size(max=500)String observacion){} }
